    "title": "obsidian 知识库不需要教程！",
    "description": "obsidian 知识库不需要教程！ 只要做了教程，就证明没用明白知识库！ 大家是不是最后还是没用知识库 我开始以为是各种博主说的废话太多，所以我一直精简到核心内容 但我发现，就算已经精简到极致，迭代之后的各种规则看得我自己头大 在我浪…",
    "column": "knowledge-workflows",
