    "description": "从几百播放，到稳定几千，再到跑出多条 10 万+。 过去一个多月，我一直在用 AI 做视频。为了打磨这套工作流，前后烧了 150 多亿 Token，抖音也涨了 1000 多粉丝。 这个过程中，我们试了大量工具，也踩了不少只有真正做过、发…",
    "column": "ai-creation",
