        "text": "拆解下怎么做： 1.选热点话题及大众熟知又不知细节的知识点，打泛人群 2.情绪化的叙事增加情绪正能量音乐 3.把视频丢给Ai做逆向工程，拆成一个个模块 4.模块组合的素材丢给codex生成视频，这种视频codex插件生成很成熟了 5.工作流自动传到剪映草稿配音乐，稍微调下细节即可"
