    "description": "公众号最近的规则变化很快，很多账号突然断流，常见的一般就是不良信息和低创作度 解决方法是检测到以后该删文删文，然后保持更新，提升内容质量 什么样的内容算得上有质量？可以看看腾讯官方刚发出来的最新规范里有一个“倡导的内容”和“拒绝的内容”…",
    "column": "content-operations",
