        "text": "它适合三种人：\n1️⃣每天都在用 Codex，但讨厌 AI 先铺垫半天的人。\n2️⃣手上项目很多，中途被打断后需要马上找回下一步的人。\n3️⃣查资料、排错、做项目时，只想先把事情往前推进的人。"
