    "statusId": "2078488413045747814",
    "source": "https://x.com/GeekCatX/status/2078488413045747814",
    "slug": "note-2078488413045747814",
    "title": "我又把这套流程优化了一版。",
    "description": "我又把这套流程优化了一版。 目前来看，这应该是我跑通过的，成本最低、操作也最简单的一套 Vox 风格视频制作方案。 整个流程只有 4 步： 第一步，用 vox-style skill 配合 Codex，拆解画面并生成分镜提示词。 第二步…",
    "column": "ai-creation",
    "category": "AI 创作",
    "readTime": "3 min",
    "blocks": [
      {
        "kind": "paragraph",
        "text": "我又把这套流程优化了一版。"
      },
      {
        "kind": "paragraph",
        "text": "目前来看，这应该是我跑通过的，成本最低、操作也最简单的一套 Vox 风格视频制作方案。"
      },
      {
        "kind": "paragraph",
        "text": "整个流程只有 4 步："
      },
      {
        "kind": "paragraph",
        "text": "第一步，用 vox-style skill 配合 Codex，拆解画面并生成分镜提示词。"
      },
      {
        "kind": "paragraph",
        "text": "第二步，用 Codex Image 2 批量产出分镜图。"
      },
      {
        "kind": "paragraph",
        "text": "第三步，把分镜图放进 Google Flow，用 Gemini Omni Flash 逐个生成视频片段。"
      },
      {
        "kind": "paragraph",
        "text": "第四步，下载全部片段，交给 ChatCut 一键剪辑成片。"
      },
      {
        "kind": "paragraph",
        "text": "简单来说就是："
      },
      {
        "kind": "paragraph",
        "text": "拆分镜 → 生图片 → 转视频 → 自动剪辑。"
      },
      {
        "kind": "paragraph",
        "text": "不需要自己从零设计画面，也不用在剪辑软件里反复对齐素材。"
      },
      {
        "kind": "paragraph",
        "text": "Google AI Pro 目前每月有 1000 个 Flow 积分，用来制作和测试短视频，成本已经能压得很低。"
      },
      {
        "kind": "paragraph",
        "text": "当然，具体能生成多少条，还是取决于视频时长、返工次数和你选择的模型。"
      },
      {
        "kind": "paragraph",
        "text": "但如果你想低成本尝试 AI 视频，而不是一开始就买一堆昂贵工具，这套工作流很值得跑一遍。"
      },
      {
        "kind": "paragraph",
        "text": "晚点我会把完整流程放到猫社群，直接开放给群友使用。"
      },
      {
        "kind": "paragraph",
        "text": "如果你也想探索 AI 视频、自媒体内容和低成本内容生产，欢迎加入猫社。"
      },
      {
        "kind": "paragraph",
        "text": "我们不只追新工具，更重要的是把工具真正变成能用的工作流。"
      },
      {
        "kind": "video",
        "src": "https://video.twimg.com/amplify_video/2078486460160987136/vid/avc1/1920x1080/kyE_C5jV_EsUFHKn.mp4?tag=29",
        "poster": "https://pbs.twimg.com/amplify_video_thumb/2078486460160987136/img/ag8iTgkz_Chpi-WE.jpg"
      }
    ],
